"use client";

import { useId, useRef, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import { Mail, ArrowRight, Check, Link2, Settings2, Rocket, MessagesSquare, X, Eye, EyeOff } from "lucide-react";
import {
  connectEmail,
  testEmailConnection,
  type EmailConnectPayload,
  type EmailConnection,
  type EmailConnectionError,
  type EmailDetected,
} from "@/store/mail/mail";

export type EmailProvider = "gmail" | "outlook" | "smtp";
export type ConnectResult = { connection: EmailConnection; message: string; warnings: string[] };
type Props = {
  /** Called with the saved connection returned by the backend. */
  onConnected: (result: ConnectResult) => void;
  /** Optional message to show on mount (e.g. after disconnecting). */
  notice?: string;
};

const providers: { id: EmailProvider; name: string; description: string }[] = [
  { id: "gmail", name: "Gmail (Google Workspace)", description: "Connect your Gmail account" },
  { id: "outlook", name: "Microsoft Outlook", description: "Connect Outlook / Microsoft 365" },
  { id: "smtp", name: "Custom SMTP", description: "Use your own SMTP (e.g., Zoho, Mailgun, etc.)" },
];

const ERROR_TITLES: Record<string, string> = {
  AUTH_FAILED: "Email or password was rejected",
  APP_PASSWORD_REQUIRED: "This account needs an app password",
  BASIC_AUTH_DISABLED: "Password sign-in is switched off",
  OAUTH_REQUIRED: "This account needs OAuth sign-in",
  UNSUPPORTED_PROVIDER: "This provider can't be connected",
  INVALID_DOMAIN: "That email domain doesn't exist",
  TLS_CERT_MISMATCH: "The server's security certificate doesn't match",
  UNREACHABLE: "Couldn't reach a mail server",
};
const ATTEMPT_LABELS: Record<string, string> = {
  ok: "Connected",
  auth_failed: "Login rejected",
  app_password_required: "App password needed",
  basic_auth_disabled: "Password login disabled",
  tls_cert: "Certificate mismatch",
  unreachable: "No response",
  blocked_private_address: "Blocked (private address)",
  dns_not_found: "Host not found",
};

type Tip = { tone: "info" | "warn"; text: string; href?: string; linkText?: string };
const APP_PASSWORD_LINK = "https://myaccount.google.com/apppasswords";
/** Pre-submit guidance from the typed domain. The server stays the source of truth. */
const domainTip = (email: string): Tip | null => {
  const d = email.split("@")[1]?.toLowerCase().trim();
  if (!d) return null;
  if (["gmail.com", "googlemail.com"].includes(d))
    return { tone: "info", text: "Gmail needs an App Password, not your normal password. Turn on 2-Step Verification first.", href: APP_PASSWORD_LINK, linkText: "Create an app password" };
  if (/^(yahoo\.|ymail\.com|rocketmail\.com)/.test(d))
    return { tone: "info", text: "Yahoo needs an App Password from your Yahoo Account Security page." };
  if (["icloud.com", "me.com", "mac.com"].includes(d))
    return { tone: "info", text: "iCloud needs an app-specific password from appleid.apple.com." };
  if (/^(outlook|hotmail|live|msn)\./.test(d))
    return { tone: "warn", text: "Personal Outlook / Hotmail accounts no longer allow password sign-in, so they can't be connected here. Use Gmail, Zoho, Hostinger or a custom-domain mailbox." };
  return null;
};
const providerTip = (p: EmailProvider | null): Tip | null =>
  p === "gmail"
    ? { tone: "info", text: "Gmail and Google Workspace need an App Password, not your normal password.", href: APP_PASSWORD_LINK, linkText: "Create an app password" }
    : p === "outlook"
      ? { tone: "info", text: "Microsoft 365 mailboxes connect only if your admin allows password (SMTP AUTH) sign-in." }
      : null;

const panel = "rounded-2xl border border-[var(--border)] bg-linear-to-br from-[var(--surface)] to-[var(--page)]";
const fieldClass = "mt-1 w-full min-w-0 rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-sm text-[var(--text)] outline-none focus:ring-2 focus:ring-blue-500";
const button = "inline-flex items-center justify-center gap-2 rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-xs font-semibold transition hover:border-blue-500 disabled:cursor-not-allowed disabled:opacity-40";
const primary = "inline-flex items-center justify-center gap-2 rounded-lg bg-[#0066ff] px-4 py-2 text-xs font-semibold text-white transition hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-40";

function Field({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) {
  return (
    <label className="block min-w-0 text-xs font-medium">
      {label}
      {children}
      {hint && <span className="mt-1 block text-[11px] font-normal text-[var(--text-soft)]">{hint}</span>}
    </label>
  );
}

export function Banner({ tone, title, children }: { tone: "success" | "error" | "warn" | "info"; title?: string; children?: ReactNode }) {
  const styles = {
    success: "border-green-500/40 bg-green-500/10",
    error: "border-red-500/40 bg-red-500/10",
    warn: "border-amber-500/40 bg-amber-500/10",
    info: "border-blue-500/40 bg-blue-500/10",
  }[tone];
  return (
    <div role={tone === "error" ? "alert" : "status"} className={`rounded-lg border px-3 py-2 text-xs leading-relaxed ${styles}`}>
      {title && <p className="font-semibold">{title}</p>}
      {children && <div className={title ? "mt-1" : ""}>{children}</div>}
    </div>
  );
}

function ProviderLogo({ provider }: { provider: EmailProvider }) {
  return <span className="grid size-10 shrink-0 place-items-center rounded-full bg-[#f4f7ff]" aria-hidden="true">{provider === "gmail" ? <svg viewBox="0 0 32 32" className="size-7"><path d="M28 16.3c0-.9-.1-1.8-.2-2.7H16v5h6.7a5.7 5.7 0 0 1-2.5 3.8v3.2h4.1c2.4-2.2 3.7-5.4 3.7-9.3Z" fill="#4285F4"/><path d="M16 28c3.4 0 6.3-1.1 8.3-3l-4.1-3.2c-1.1.7-2.5 1.1-4.2 1.1-3.2 0-5.9-2.1-6.9-5H4.9v3.3A12.5 12.5 0 0 0 16 28Z" fill="#34A853"/><path d="M9.1 17.9a7.5 7.5 0 0 1 0-4.8V9.8H4.9a12.4 12.4 0 0 0 0 11.4Z" fill="#FBBC05"/><path d="M16 8.1c1.9 0 3.6.7 4.9 1.9l3.6-3.5A12.1 12.1 0 0 0 16 3a12.5 12.5 0 0 0-11.1 6.8l4.2 3.3c1-2.9 3.7-5 6.9-5Z" fill="#EA4335"/></svg> : provider === "outlook" ? <svg viewBox="0 0 36 36" className="size-8"><rect x="12" y="5" width="18" height="24" rx="2" fill="#0078d4"/><path d="M13 13h17v8H13Z" fill="#28a8ea"/><path d="m9 18 12 9 12-9v13H9Z" fill="#1490df"/><path d="m9 18 12 8 12-8" fill="#55c4fa"/><rect x="3" y="11" width="16" height="18" rx="1" fill="#0364b8"/><text x="11" y="24" fill="white" fontSize="13" fontWeight="700" textAnchor="middle">O</text></svg> : <Mail size={27} className="text-[#16366f]"/>}</span>;
}

/**
 * Credential form shared by the setup dialog and the "Change mailbox" dialog.
 * Talks to the real backend: test (detect + verify, saves nothing) and connect (detect + verify + save).
 * `provider: null` = plain auto-detect; "smtp" = manual server settings are required.
 */
export function ConnectForm({
  provider,
  initial,
  onBusy,
  onDone,
}: {
  provider: EmailProvider | null;
  initial?: { email?: string; fromName?: string };
  onBusy?: (busy: boolean) => void;
  onDone: (result: ConnectResult) => void;
}) {
  const manual = provider === "smtp";
  const [email, setEmail] = useState(initial?.email ?? "");
  const [fromName, setFromName] = useState(initial?.fromName ?? "");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showAdvanced, setShowAdvanced] = useState(manual);
  const [adv, setAdv] = useState({ smtpHost: "", smtpPort: "587", smtpUser: "", imapHost: "", imapPort: "993" });
  const [busy, setBusy] = useState<null | "test" | "connect">(null);
  const [error, setError] = useState<EmailConnectionError | null>(null);
  const [detected, setDetected] = useState<EmailDetected | null>(null);

  const tip = domainTip(email) ?? providerTip(provider);
  const canSubmit =
    /^\S+@\S+\.\S+$/.test(email.trim()) && password.length > 0 && (!manual || adv.smtpHost.trim() !== "") && !busy;

  const payload = (): EmailConnectPayload => {
    const p: EmailConnectPayload = { email: email.trim(), password, ...(fromName.trim() ? { fromName: fromName.trim() } : {}) };
    if (showAdvanced && adv.smtpHost.trim()) {
      p.advanced = {
        smtpHost: adv.smtpHost.trim(),
        smtpPort: Number(adv.smtpPort) || 587,
        ...(adv.smtpUser.trim() ? { smtpUser: adv.smtpUser.trim() } : {}),
        ...(adv.imapHost.trim() ? { imapHost: adv.imapHost.trim(), imapPort: Number(adv.imapPort) || 993 } : {}),
      };
    }
    return p;
  };

  const setBusyState = (b: typeof busy) => {
    setBusy(b);
    onBusy?.(!!b);
  };

  async function run(kind: "test" | "connect") {
    if (!canSubmit) return;
    setBusyState(kind);
    setError(null);
    setDetected(null);
    const fail = (e: EmailConnectionError) => {
      setError(e);
      if (e.needsAdvanced) setShowAdvanced(true);
    };
    if (kind === "test") {
      const r = await testEmailConnection(payload());
      if (r.ok) setDetected(r.data.detected);
      else fail(r.error);
    } else {
      const r = await connectEmail(payload());
      if (r.ok) {
        setPassword("");
        onDone({ connection: r.data.connection, message: r.data.message, warnings: r.data.warnings ?? [] });
      } else fail(r.error);
    }
    setBusyState(null);
  }

  const onSubmit = (e: FormEvent) => {
    e.preventDefault();
    run("connect");
  };

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-3">
      <fieldset disabled={!!busy} className="space-y-3">
        <Field label="Email address">
          <input type="email" autoComplete="email" inputMode="email" required autoFocus className={fieldClass} placeholder="you@yourcompany.com" value={email} onChange={(e) => setEmail(e.target.value)} />
        </Field>
        <Field label="Sender name (optional)" hint="Shown to customers. Defaults to your account name.">
          <input type="text" maxLength={100} className={fieldClass} placeholder="Priya from Acme" value={fromName} onChange={(e) => setFromName(e.target.value)} />
        </Field>
        <Field label="Mailbox password or app password" hint="Stored encrypted. It is never shown again after you save.">
          <div className="relative">
            <input type={showPassword ? "text" : "password"} autoComplete="new-password" required className={`${fieldClass} pr-11`} value={password} onChange={(e) => setPassword(e.target.value)} />
            <button type="button" onClick={() => setShowPassword((s) => !s)} aria-label={showPassword ? "Hide password" : "Show password"} className="absolute inset-y-0 right-0 mt-1 flex w-11 items-center justify-center text-[var(--text-soft)] hover:text-[var(--text)]">
              {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
            </button>
          </div>
        </Field>

        {tip && (
          <Banner tone={tip.tone}>
            {tip.text}{" "}
            {tip.href && <a href={tip.href} target="_blank" rel="noopener noreferrer" className="font-medium underline">{tip.linkText}</a>}
          </Banner>
        )}

        {!manual && (
          <button type="button" aria-expanded={showAdvanced} onClick={() => setShowAdvanced((s) => !s)} className="text-xs font-medium text-blue-400 hover:underline">
            {showAdvanced ? "Hide server settings" : "Enter server settings manually"}
          </button>
        )}
        {showAdvanced && (
          <div className="space-y-3 rounded-lg border border-[var(--border)] bg-[var(--surface-2)] p-3">
            <p className="text-xs text-[var(--text-soft)]">
              {manual ? "Ask your email host for these settings." : "Only needed if automatic detection can't find your server."}
            </p>
            <div className="grid grid-cols-[2fr_1fr] gap-3">
              <Field label="Outgoing (SMTP) server">
                <input className={fieldClass} placeholder="smtp.yourhost.com" required={manual} value={adv.smtpHost} onChange={(e) => setAdv({ ...adv, smtpHost: e.target.value })} />
              </Field>
              <Field label="Port" hint="465 = SSL, 587 = STARTTLS">
                <input type="number" min={1} max={65535} className={fieldClass} value={adv.smtpPort} onChange={(e) => setAdv({ ...adv, smtpPort: e.target.value })} />
              </Field>
            </div>
            <Field label="SMTP username" hint="Leave empty to use your email address.">
              <input className={fieldClass} value={adv.smtpUser} onChange={(e) => setAdv({ ...adv, smtpUser: e.target.value })} />
            </Field>
            <div className="grid grid-cols-[2fr_1fr] gap-3">
              <Field label="Incoming (IMAP) server" hint="Optional. Used to save copies in Sent.">
                <input className={fieldClass} placeholder="imap.yourhost.com" value={adv.imapHost} onChange={(e) => setAdv({ ...adv, imapHost: e.target.value })} />
              </Field>
              <Field label="Port">
                <input type="number" min={1} max={65535} className={fieldClass} value={adv.imapPort} onChange={(e) => setAdv({ ...adv, imapPort: e.target.value })} />
              </Field>
            </div>
          </div>
        )}
      </fieldset>

      {error && (
        <div className="space-y-2">
          <Banner tone="error" title={(error.code && ERROR_TITLES[error.code]) || "Couldn't connect"}>
            <p>{error.message}</p>
            {error.hint && <p className="mt-1">{error.hint}</p>}
            {error.needsAdvanced && (
              <p className="mt-1">{showAdvanced ? "We couldn't find your server automatically. Fill in the server settings above and try again." : "Try entering the server settings manually."}</p>
            )}
          </Banner>
          {!!error.tried?.length && (
            <details className="rounded-lg border border-[var(--border)] text-xs">
              <summary className="cursor-pointer px-3 py-2">What we tried ({error.tried.length})</summary>
              <ul className="divide-y divide-[var(--border)] border-t border-[var(--border)]">
                {error.tried.map((t, i) => (
                  <li key={`${t.host}-${t.port}-${i}`} className="flex flex-wrap justify-between gap-2 px-3 py-1.5">
                    <span>{t.host}:{t.port}</span>
                    <span className="text-[var(--text-soft)]">{ATTEMPT_LABELS[t.result] ?? t.result}</span>
                  </li>
                ))}
              </ul>
            </details>
          )}
        </div>
      )}

      {detected && (
        <div className="space-y-2">
          <Banner tone="success" title="Login works">
            We found <strong>{detected.providerLabel}</strong> at <strong>{detected.smtp.host}:{detected.smtp.port}</strong>.{" "}
            {detected.saveToSent ? `Sent copies will be saved to “${detected.sentFolder}”.` : "Nothing is saved yet. Select Connect to finish."}
          </Banner>
          {detected.warnings?.map((w) => <Banner key={w} tone="warn">{w}</Banner>)}
        </div>
      )}

      <div className="flex flex-wrap justify-end gap-2">
        <button type="button" className={button} disabled={!canSubmit} onClick={() => run("test")}>
          {busy === "test" ? "Testing…" : "Test connection"}
        </button>
        <button type="submit" className={primary} disabled={!canSubmit}>
          {busy === "connect" ? "Connecting…" : "Connect mailbox"}
        </button>
      </div>
    </form>
  );
}

/**
 * Setup-state workspace (no mailbox connected). Mounted by page.tsx only when the backend
 * reports `connected: false`. On success it hands the saved connection back to the page.
 */
export default function EmailWorkspaceSetup({ onConnected, notice: initialNotice = "" }: Props) {
  const [modal, setModal] = useState<"select" | "connect">("select");
  const [provider, setProvider] = useState<EmailProvider>("gmail");
  const [notice, setNotice] = useState(initialNotice);
  const [busy, setBusy] = useState(false);
  const dialog = useRef<HTMLDialogElement>(null);
  const uid = useId();
  const open = (next: typeof modal) => { setModal(next); dialog.current?.showModal(); };
  const close = () => { if (!busy) dialog.current?.close(); };
  const connect = (next: EmailProvider) => { setProvider(next); open("connect"); };

  const providerCards = <div className="grid gap-2">{providers.map(p => <article key={p.id} className="flex min-w-0 items-center gap-3 rounded-xl border border-[var(--border)] bg-[var(--surface-2)] px-2.5 py-2"><ProviderLogo provider={p.id}/><div className="min-w-0 flex-1"><h3 className="text-[12px] font-bold @min-[1100px]:text-sm">{p.name}</h3><p className="mt-1 text-[10px] leading-tight text-[var(--text-soft)] @min-[1100px]:text-xs">{p.description}</p></div><button type="button" onClick={() => connect(p.id)} className={`${primary} shrink-0 px-3`}>Connect<ArrowRight size={16}/></button></article>)}</div>;

  return <section aria-label="Email workspace" className="@container w-full min-w-0 text-[var(--text)] [&_button]:cursor-pointer [&_button]:focus-visible:outline-2 [&_button]:focus-visible:outline-offset-2 [&_button]:focus-visible:outline-blue-500">
    <div className="flex items-center gap-4"><span className="grid size-12 shrink-0 place-items-center rounded-xl bg-linear-to-br from-blue-950 via-blue-600 to-blue-950 text-white"><Mail size={30}/></span><div className="min-w-0"><h1 className="text-2xl leading-tight font-bold tracking-tight">Email Workspace</h1><p className="mt-1 text-xs text-[var(--text-soft)] @min-[1000px]:text-sm">No email account connected yet. Choose a provider below to get started.</p></div></div>
    {notice && <div role="status" className="mt-3 flex items-center justify-between gap-3 rounded-lg bg-blue-500/10 px-3 py-2 text-xs"><span>{notice}</span><button type="button" aria-label="Dismiss notification" onClick={() => setNotice("")}><X size={15}/></button></div>}
    <div className="mt-3">
      <div className={`${panel} grid min-w-0 grid-cols-1 @min-[900px]:grid-cols-[minmax(0,1.72fr)_minmax(0,1fr)]`}>
        <div className="grid min-w-0 grid-cols-[minmax(0,.9fr)_minmax(0,1.1fr)] items-center @max-[550px]:grid-cols-1">
          <div className="relative h-full min-h-[235px] min-w-0 overflow-hidden rounded-l-2xl @max-[550px]:hidden"><svg viewBox="242 165 346 231" preserveAspectRatio="xMidYMid meet" className="absolute inset-0 h-full w-full" role="img" aria-label="Glowing email envelope and paper plane illustration"><image href={emailArtwork} width="1536" height="498"/></svg></div>
          <div className="min-w-0 py-4 pr-3 pl-2 @max-[550px]:p-4"><h2 className="text-xl leading-tight font-bold tracking-tight @min-[1150px]:text-2xl">Connect Your Email Channel</h2><p className="mt-2 text-xs leading-snug text-[var(--text-soft)]">Integrate your email accounts to manage inbox, send campaigns and automate follow-ups from OrbitFlow.</p><ul className="mt-3 space-y-1.5 text-[11px] @min-[1150px]:text-xs">{["Connect multiple email accounts (Gmail, Outlook, custom SMTP)", "Manage all email conversations in a unified inbox", "Send bulk and personalized email campaigns", "Use templates, automation and AI-powered replies", "Track delivery, open, reply and click performance"].map(text => <li key={text} className="flex items-start gap-2"><span className="grid size-5 shrink-0 place-items-center rounded-full bg-linear-to-b from-blue-300 to-indigo-500 text-white"><Check size={13} strokeWidth={3}/></span><span className="pt-0.5">{text}</span></li>)}</ul></div>
        </div>
        <section className="min-w-0 rounded-2xl border border-[var(--border)] bg-[var(--page)]/20 p-3"><h2 className="mb-3 flex items-center gap-4 text-sm font-bold"><span className="grid size-8 place-items-center rounded-lg bg-blue-500/10 text-blue-400"><MessagesSquare size={24}/></span>Choose an Email Provider</h2>{providerCards}</section>
      </div>
      <div className={`${panel} mt-2 grid grid-cols-3 items-center gap-3 px-4 py-3 @min-[1050px]:grid-cols-[1.1fr_repeat(3,1.25fr)]`}>
        <div className="hidden @min-[1050px]:block"><h2 className="text-base font-bold">Get Started in 3 Steps</h2><p className="mt-1 text-xs text-[var(--text-soft)]">Set up your email workspace in minutes.</p></div>
        <button type="button" onClick={() => open("select")} className="flex min-w-0 items-center gap-3 rounded-xl text-left transition hover:bg-[var(--surface-2)]"><span className="self-start rounded-full bg-[#0066ff] px-2 py-1 text-[10px] leading-none text-white">1</span><span className="hidden size-14 shrink-0 place-items-center rounded-full bg-linear-to-br from-blue-600/70 to-blue-900/70 text-blue-200 @min-[800px]:grid"><Link2 size={32}/></span><span className="min-w-0 flex-1"><strong className="block text-xs @min-[1200px]:text-sm">Connect Account</strong><span className="mt-1 block text-[10px] leading-snug text-[var(--text-soft)] @min-[1200px]:text-xs">Add Gmail, Outlook or SMTP</span></span><ArrowRight size={23} className="hidden shrink-0 text-blue-200 @min-[1150px]:block"/></button>
        {[{title:"Configure Settings",text:"Available after connecting your account",icon:Settings2},{title:"Start Using",text:"Manage your email after setup is complete",icon:Rocket}].map(({title,text,icon:Icon},i) => <div key={title} className="flex min-w-0 items-center gap-3"><span className="self-start rounded-full bg-[#0066ff] px-2 py-1 text-[10px] leading-none text-white">{i+2}</span><span className="hidden size-14 shrink-0 place-items-center rounded-full bg-linear-to-br from-blue-600/70 to-blue-900/70 text-blue-200 @min-[800px]:grid"><Icon size={32}/></span><span className="min-w-0 flex-1"><strong className="block text-xs @min-[1200px]:text-sm">{title}</strong><span className="mt-1 block text-[10px] leading-snug text-[var(--text-soft)] @min-[1200px]:text-xs">{text}</span></span>{i===0&&<ArrowRight size={23} className="hidden shrink-0 text-blue-200 @min-[1150px]:block"/>}</div>)}
      </div>
    </div>
    <dialog ref={dialog} aria-labelledby={`${uid}-dialog`} onCancel={e => { if (busy) e.preventDefault(); }} onClose={() => setModal("select")} className="fixed inset-0 m-auto max-h-[90dvh] w-[min(570px,94vw)] overflow-y-auto rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-5 text-[var(--text)] shadow-2xl backdrop:bg-black/65">
      <div className="mb-4 flex items-center justify-between gap-3"><h2 id={`${uid}-dialog`} className="text-lg font-bold">{modal === "select" ? "Choose an email provider" : `Connect ${providers.find(p => p.id === provider)?.name}`}</h2><button type="button" disabled={busy} onClick={close} aria-label="Close dialog" className={button}><X size={17}/></button></div>
      {modal === "select" && providerCards}
      {modal === "connect" && <div className="space-y-4">
        <div className="flex items-center gap-3"><ProviderLogo provider={provider}/><p className="text-sm text-[var(--text-soft)]">{provider === "smtp" ? "Enter your mailbox login and your provider’s server settings." : "Enter your mailbox email and password. We find the server settings for you."}</p></div>
        <ConnectForm key={provider} provider={provider} onBusy={setBusy} onDone={(r) => { dialog.current?.close(); onConnected(r); }} />
      </div>}
    </dialog>
  </section>;
}


// Embedded reference illustration. The SVG viewBox displays the artwork only.
const emailArtwork = "data:image/png;base64,";
